<!DOCTYPE html> <html lang="en"> <head> <meta charset="UTF-8"> <title>Pharma ERP - Auth</title> <meta name="viewport" content="width=device-width, initial-scale=1"> <!-- Bootstrap --> <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"> <style> body { background: linear-gradient(135deg, #0f2027, #203a43, #2c5364); height: 100vh; display: flex; align-items: center; justify-content: center; } .auth-card { width: 420px; border-radius: 15px; box-shadow: 0 20px 40px rgba(0,0,0,0.3); } .toggle-link { cursor: pointer; color: #0d6efd; } .form-section { display: none; } .form-section.active { display: block; } </style> </head> <body> <div class="card auth-card p-4 bg-white"> <h4 class="text-center mb-4 fw-bold">Pharma ERP</h4> {{-- LOGIN FORM --}} <div id="loginForm" class="form-section active"> <form method="POST" action="{{ route('login') }}"> @csrf <div class="mb-3"> <label>Email</label> <input type="email" name="email" class="form-control" required> @error('email') <small class="text-danger">{{ $message }}</small> @enderror </div> <div class="mb-3"> <label>Password</label> <input type="password" name="password" class="form-control" required> </div> <button class="btn btn-primary w-100">Login</button> </form> <div class="text-center mt-3"> <span class="toggle-link" onclick="showRegister()">Create Account</span> | <span class="toggle-link" onclick="showReset()">Forgot Password?</span> </div> </div> {{-- REGISTER FORM --}} <div id="registerForm" class="form-section"> <form method="POST" action="{{ route('register') }}"> @csrf <div class="mb-3"> <label>Name</label> <input type="text" name="name" class="form-control" required> </div> <div class="mb-3"> <label>Email</label> <input type="email" name="email" class="form-control" required> </div> <div class="mb-3"> <label>Password</label> <input type="password" name="password" class="form-control" required> </div> <div class="mb-3"> <label>Confirm Password</label> <input type="password" name="password_confirmation" class="form-control" required> </div> <button class="btn btn-success w-100">Register</button> </form> <div class="text-center mt-3"> <span class="toggle-link" onclick="showLogin()">Back to Login</span> </div> </div> {{-- RESET FORM --}} <div id="resetForm" class="form-section"> <form method="POST" action="{{ route('password.email') }}"> @csrf <div class="mb-3"> <label>Email</label> <input type="email" name="email" class="form-control" required> </div> <button class="btn btn-warning w-100">Send Reset Link</button> </form> <div class="text-center mt-3"> <span class="toggle-link" onclick="showLogin()">Back to Login</span> </div> </div> </div> <script> function showLogin() { document.getElementById('loginForm').classList.add('active'); document.getElementById('registerForm').classList.remove('active'); document.getElementById('resetForm').classList.remove('active'); } function showRegister() { document.getElementById('loginForm').classList.remove('active'); document.getElementById('registerForm').classList.add('active'); document.getElementById('resetForm').classList.remove('active'); } function showReset() { document.getElementById('loginForm').classList.remove('active'); document.getElementById('registerForm').classList.remove('active'); document.getElementById('resetForm').classList.add('active'); } </script> </body> </html>